            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.8 * (a + b):
                coord[i] += occ[j] * exp(-(d / (1.3 * (a + b))) ** 6)
    weight = 0.0
    value = 0.0
    for i in range(n):
        if radii[i] is not None and radii[i] > 0:
            weight += occ[i]
            value += occ[i] * coord[i]
    return value / weight if weight > 0 else 0.0

