    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    first = [None for x in sites]
    second = [None for x in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            if first[i] is None or d < first[i]:
                second[i] = first[i]
                first[i] = d
            elif second[i] is None or d < second[i]:
                second[i] = d
    total = 0.0
    value = 0.0
    for i in range(n):
        if first[i] is not None and second[i] is not None and second[i] > 0:
            value += occ[i] * (second[i] - first[i]) / second[i]
            total += occ[i]
    return value / total if total > 0 else 0.0
